from collections import deque
def solve(I):
    h,w=len(I),len(I[0]); out=[row[:] for row in I]
    seen=set()
    q=deque()
    for r in range(h):
        for c in (0,w-1):
            if I[r][c]==0 and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if I[r][c]==0 and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            if 0<=rr<h and 0<=cc<w and (rr,cc) not in seen and I[rr][cc]==0:
                seen.add((rr,cc)); q.append((rr,cc))
    for r in range(h):
        for c in range(w):
            if I[r][c]!=0: continue
            if (r,c) in seen: out[r][c]=2
            else: out[r][c]=3
    return out
